-- =====================================================================
-- StreamHub Database Schema
-- Group ID: 2026-Y2-S1-MLB-B2G2-07
--
-- This is the single source of truth for all six members' local
-- StreamHubDB instances. Every member runs this script once against
-- their own local Microsoft SQL Server to get an identical schema.
--
-- All primary keys are UUID (UNIQUEIDENTIFIER), generated by the
-- Spring Boot / Hibernate layer (GenerationType.UUID) rather than the
-- database.
-- =====================================================================

-- ---------------------------------------------------------------------
-- USER
-- ---------------------------------------------------------------------
CREATE TABLE [User] (
    user_id         UNIQUEIDENTIFIER   NOT NULL PRIMARY KEY,
    username        NVARCHAR(50)       NOT NULL,
    email           NVARCHAR(100)      NOT NULL,
    first_name      NVARCHAR(50)       NOT NULL DEFAULT 'Unknown',
    last_name       NVARCHAR(50)       NOT NULL DEFAULT 'Unknown',
    date_of_birth   DATE               NOT NULL DEFAULT '2000-01-01',
    password_hash   NVARCHAR(255)      NOT NULL,
    role            NVARCHAR(20)       NOT NULL,
    status          VARCHAR(20)        NULL DEFAULT 'ACTIVE',
    bio             NVARCHAR(300)      NULL,
    avatar_url      NVARCHAR(255)      NULL,
    cover_image_url NVARCHAR(255)      NULL,
    has_set_interests BIT              NOT NULL DEFAULT 0, -- migration note: existing accounts default to 0 and trigger onboarding once on next login
    created_at      DATETIME2          NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at      DATETIME2          NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT UQ_User_Username UNIQUE (username),
    CONSTRAINT UQ_User_Email UNIQUE (email),
    CONSTRAINT CK_User_Role CHECK (role IN ('USER', 'CONTENT_MODERATOR', 'ADMINISTRATOR'))
);
GO

-- ---------------------------------------------------------------------
-- CATEGORIES
-- ---------------------------------------------------------------------
CREATE TABLE categories (
    id              UNIQUEIDENTIFIER   NOT NULL PRIMARY KEY,
    name            VARCHAR(100)       NOT NULL,
    description     VARCHAR(500)       NULL,
    created_at      DATETIME2          NOT NULL,
    CONSTRAINT UQ_categories_Name UNIQUE (name)
);
GO

-- ---------------------------------------------------------------------
-- VIDEO
-- ---------------------------------------------------------------------
CREATE TABLE Video (
    video_id            UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    uploader_id         UNIQUEIDENTIFIER  NOT NULL,
    category_id         UNIQUEIDENTIFIER  NULL,
    title               NVARCHAR(150)     NOT NULL,
    description         NVARCHAR(MAX)     NULL,
    file_path           NVARCHAR(500)     NOT NULL,
    thumbnail_path      NVARCHAR(500)     NULL,
    thumbnail_url       NVARCHAR(255)     NOT NULL,
    duration_seconds    INT               NULL,
    privacy             NVARCHAR(10)      NOT NULL DEFAULT 'PUBLIC',
    view_count          INT               NOT NULL DEFAULT 0,
    is_hidden           BIT               NOT NULL DEFAULT 0,
    created_at          DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at          DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT FK_Video_Uploader FOREIGN KEY (uploader_id) REFERENCES [User](user_id),
    CONSTRAINT FK_Video_Category FOREIGN KEY (category_id) REFERENCES categories(id),
    CONSTRAINT CK_Video_Duration CHECK (duration_seconds IS NULL OR duration_seconds >= 0),
    CONSTRAINT CK_Video_Privacy CHECK (privacy IN ('PUBLIC','PRIVATE'))
);
GO
CREATE INDEX IX_Video_Uploader ON Video(uploader_id);
CREATE INDEX IX_Video_Category ON Video(category_id);
GO

-- ---------------------------------------------------------------------
-- PLAYLIST
-- ---------------------------------------------------------------------
CREATE TABLE Playlist (
    playlist_id     UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    owner_id        UNIQUEIDENTIFIER  NOT NULL,
    name            NVARCHAR(100)     NOT NULL,
    description     NVARCHAR(255)     NULL,
    privacy         VARCHAR(50)       NULL DEFAULT 'PUBLIC',
    thumbnail_url   VARCHAR(255)      NULL,
    is_hidden       BIT               NOT NULL DEFAULT 0,
    created_at      DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at      DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT FK_Playlist_Owner FOREIGN KEY (owner_id) REFERENCES [User](user_id)
);
GO
CREATE INDEX IX_Playlist_Owner ON Playlist(owner_id);
GO

-- ---------------------------------------------------------------------
-- PLAYLIST_VIDEO
-- ---------------------------------------------------------------------
CREATE TABLE playlist_video (
    playlist_video_id  UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    playlist_id        UNIQUEIDENTIFIER  NOT NULL,
    video_id           UNIQUEIDENTIFIER  NOT NULL,
    position           INT               NOT NULL,
    added_at           DATETIME2         NOT NULL,
    CONSTRAINT FK_playlist_video_Playlist FOREIGN KEY (playlist_id) REFERENCES Playlist(playlist_id),
    CONSTRAINT FK_playlist_video_Video FOREIGN KEY (video_id) REFERENCES Video(video_id) ON DELETE CASCADE,
    CONSTRAINT UQ_playlist_video_Position UNIQUE (playlist_id, position)
);
GO
CREATE INDEX IX_playlist_video_Playlist ON playlist_video(playlist_id);
CREATE INDEX IX_playlist_video_Video ON playlist_video(video_id);
GO

-- ---------------------------------------------------------------------
-- COMMENT
-- ---------------------------------------------------------------------
CREATE TABLE Comment (
    comment_id          UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    video_id            UNIQUEIDENTIFIER  NOT NULL,
    user_id             UNIQUEIDENTIFIER  NOT NULL,
    parent_comment_id   UNIQUEIDENTIFIER  NULL,
    content             NVARCHAR(1000)    NOT NULL,
    is_hidden           BIT               NOT NULL DEFAULT 0,
    created_at          DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at          DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT FK_Comment_Video FOREIGN KEY (video_id) REFERENCES Video(video_id) ON DELETE CASCADE,
    CONSTRAINT FK_Comment_User FOREIGN KEY (user_id) REFERENCES [User](user_id),
    CONSTRAINT FK_Comment_Parent FOREIGN KEY (parent_comment_id) REFERENCES Comment(comment_id)
);
GO
CREATE INDEX IX_Comment_Video ON Comment(video_id);
CREATE INDEX IX_Comment_User ON Comment(user_id);
CREATE INDEX IX_Comment_Parent ON Comment(parent_comment_id);
GO

-- ---------------------------------------------------------------------
-- LIKE
-- ---------------------------------------------------------------------
CREATE TABLE [Like] (
    like_id       UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    user_id       UNIQUEIDENTIFIER  NOT NULL,
    video_id      UNIQUEIDENTIFIER  NOT NULL,
    created_at    DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at    DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT FK_Like_User FOREIGN KEY (user_id) REFERENCES [User](user_id),
    CONSTRAINT FK_Like_Video FOREIGN KEY (video_id) REFERENCES Video(video_id) ON DELETE CASCADE,
    CONSTRAINT UQ_Like_UserVideo UNIQUE (user_id, video_id)
);
GO
CREATE INDEX IX_Like_Video ON [Like](video_id);
GO

-- ---------------------------------------------------------------------
-- DISLIKE
-- ---------------------------------------------------------------------
CREATE TABLE dislike (
    dislike_id    UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    user_id       UNIQUEIDENTIFIER  NOT NULL,
    video_id      UNIQUEIDENTIFIER  NOT NULL,
    created_at    DATETIME2         NOT NULL,
    CONSTRAINT FK_dislike_User FOREIGN KEY (user_id) REFERENCES [User](user_id),
    CONSTRAINT FK_dislike_Video FOREIGN KEY (video_id) REFERENCES Video(video_id) ON DELETE CASCADE,
    CONSTRAINT UQ_dislike_UserVideo UNIQUE (user_id, video_id)
);
GO
CREATE INDEX IX_dislike_Video ON dislike(video_id);
GO

-- ---------------------------------------------------------------------
-- REFRESH_TOKEN
-- ---------------------------------------------------------------------
CREATE TABLE refresh_token (
    id              UNIQUEIDENTIFIER   NOT NULL PRIMARY KEY,
    user_id         UNIQUEIDENTIFIER   NOT NULL,
    token_hash      VARCHAR(255)       NOT NULL,
    expires_at      DATETIME2          NOT NULL,
    created_at      DATETIME2          NOT NULL,
    revoked         BIT                NOT NULL,
    CONSTRAINT FK_refresh_token_User FOREIGN KEY (user_id) REFERENCES [User](user_id) ON DELETE CASCADE
);
GO
CREATE INDEX IX_refresh_token_User ON refresh_token(user_id);
GO

-- ---------------------------------------------------------------------
-- NOTIFICATION
-- ---------------------------------------------------------------------
CREATE TABLE notification (
    id                   UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    user_id              UNIQUEIDENTIFIER  NOT NULL,
    type                 VARCHAR(50)       NOT NULL,
    title                VARCHAR(150)      NOT NULL,
    message              VARCHAR(500)      NOT NULL,
    related_entity_type  VARCHAR(50)       NULL,
    related_entity_id    UNIQUEIDENTIFIER  NULL,
    is_read              BIT               NOT NULL,
    created_at           DATETIME2         NOT NULL,
    CONSTRAINT FK_notification_User FOREIGN KEY (user_id) REFERENCES [User](user_id) ON DELETE CASCADE
);
GO
CREATE INDEX IX_notification_User ON notification(user_id);
GO

-- ---------------------------------------------------------------------
-- REPORT
-- ---------------------------------------------------------------------
CREATE TABLE report (
    id                   UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    reporter_id          UNIQUEIDENTIFIER  NOT NULL,
    reportable_type      VARCHAR(20)       NULL,
    reportable_id        UNIQUEIDENTIFIER  NULL,
    reason               VARCHAR(50)       NULL,
    details              VARCHAR(500)      NULL,
    status               VARCHAR(20)       NULL,
    moderator_id         UNIQUEIDENTIFIER  NULL,
    moderator_action     VARCHAR(20)       NULL,
    action_reason        VARCHAR(500)      NULL,
    created_at           DATETIME2         NOT NULL,
    resolved_at          DATETIME2         NULL,
    CONSTRAINT FK_report_Reporter FOREIGN KEY (reporter_id) REFERENCES [User](user_id),
    CONSTRAINT FK_report_Moderator FOREIGN KEY (moderator_id) REFERENCES [User](user_id)
);
GO
CREATE INDEX IX_report_Reporter ON report(reporter_id);
CREATE INDEX IX_report_Moderator ON report(moderator_id);
GO

-- ---------------------------------------------------------------------
-- WATCH_HISTORY
-- ---------------------------------------------------------------------
CREATE TABLE watch_history (
    watch_history_id         UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    user_id                  UNIQUEIDENTIFIER  NOT NULL,
    video_id                 UNIQUEIDENTIFIER  NOT NULL,
    last_position            INT               NOT NULL DEFAULT 0,
    watched_at               DATETIME2         NOT NULL,
    watch_duration_seconds   INT               NULL,
    updated_at               DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT FK_watch_history_User FOREIGN KEY (user_id) REFERENCES [User](user_id),
    CONSTRAINT FK_watch_history_Video FOREIGN KEY (video_id) REFERENCES Video(video_id) ON DELETE CASCADE,
    CONSTRAINT UQ_watch_history_User_Video UNIQUE (user_id, video_id)
);
GO
CREATE INDEX IX_watch_history_User ON watch_history(user_id, updated_at DESC);
CREATE INDEX IX_watch_history_Video ON watch_history(video_id);
GO

-- ---------------------------------------------------------------------
-- USER_CATEGORY_PREFERENCE
-- ---------------------------------------------------------------------
CREATE TABLE UserCategoryPreference (
    id            UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    user_id       UNIQUEIDENTIFIER  NOT NULL,
    category_id   UNIQUEIDENTIFIER  NOT NULL,
    created_at    DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT FK_UserCategoryPreference_User FOREIGN KEY (user_id) REFERENCES [User](user_id) ON DELETE CASCADE,
    CONSTRAINT FK_UserCategoryPreference_Category FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE,
    CONSTRAINT UQ_UserCategoryPreference_UserCategory UNIQUE (user_id, category_id)
);
GO
CREATE INDEX IX_UserCategoryPreference_User ON UserCategoryPreference(user_id);
GO

-- ---------------------------------------------------------------------
-- VIDEO_VIEW_EVENT
-- ---------------------------------------------------------------------
-- Note: In production, a retention/cleanup job (e.g. deleting rows older than 30 days) is recommended.
CREATE TABLE VideoViewEvent (
    id          UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    video_id    UNIQUEIDENTIFIER  NOT NULL,
    user_id     UNIQUEIDENTIFIER  NULL,
    viewed_at   DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT FK_VideoViewEvent_Video FOREIGN KEY (video_id) REFERENCES Video(video_id) ON DELETE CASCADE,
    CONSTRAINT FK_VideoViewEvent_User FOREIGN KEY (user_id) REFERENCES [User](user_id)
);
GO
CREATE INDEX IX_VideoViewEvent_Video_ViewedAt ON VideoViewEvent(video_id, viewed_at);
GO

-- ---------------------------------------------------------------------
-- SYNC_LOG
-- ---------------------------------------------------------------------
CREATE TABLE SyncLog (
    sync_log_id     INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    file_name       NVARCHAR(255)     NOT NULL,
    applied_at      DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT UQ_SyncLog_FileName UNIQUE (file_name)
);
GO

-- ---------------------------------------------------------------------
-- HELP_TOPIC
-- ---------------------------------------------------------------------
CREATE TABLE HelpTopic (
    id              UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    section         NVARCHAR(150)     NOT NULL,
    question        NVARCHAR(255)     NOT NULL,
    answer          NVARCHAR(2000)    NOT NULL,
    display_order   INT               NOT NULL DEFAULT 0,
    created_at      DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at      DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME()
);
GO
CREATE INDEX IX_HelpTopic_Section_DisplayOrder ON HelpTopic(section, display_order);
GO

-- ---------------------------------------------------------------------
-- FOLLOW
-- ---------------------------------------------------------------------
CREATE TABLE Follow (
    id              UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY DEFAULT NEWID(),
    follower_id     UNIQUEIDENTIFIER  NOT NULL,
    following_id    UNIQUEIDENTIFIER  NOT NULL,
    created_at      DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT fk_follow_follower FOREIGN KEY (follower_id) REFERENCES [User](user_id) ON DELETE CASCADE,
    CONSTRAINT fk_follow_following FOREIGN KEY (following_id) REFERENCES [User](user_id) ON DELETE NO ACTION,
    CONSTRAINT uq_follow_pair UNIQUE (follower_id, following_id),
    CONSTRAINT ck_follow_no_self CHECK (follower_id <> following_id)
);
GO
CREATE INDEX idx_follow_following_id ON Follow(following_id);
GO

-- ---------------------------------------------------------------------
-- COMMENT_LIKE
-- ---------------------------------------------------------------------
CREATE TABLE CommentLike (
    id          UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    comment_id  UNIQUEIDENTIFIER  NOT NULL,
    user_id     UNIQUEIDENTIFIER  NOT NULL,
    created_at  DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT FK_CommentLike_Comment FOREIGN KEY (comment_id) REFERENCES Comment(comment_id) ON DELETE CASCADE,
    CONSTRAINT FK_CommentLike_User FOREIGN KEY (user_id) REFERENCES [User](user_id),
    CONSTRAINT UQ_CommentLike_User_Comment UNIQUE (comment_id, user_id)
);
GO
CREATE INDEX IX_CommentLike_Comment ON CommentLike(comment_id);
CREATE INDEX IX_CommentLike_User ON CommentLike(user_id);
GO

-- ---------------------------------------------------------------------
-- TRIGGERS
-- ---------------------------------------------------------------------
CREATE OR ALTER TRIGGER dbo.trg_DeleteVideo_Cleanup
ON [dbo].[Video]
INSTEAD OF DELETE
AS
BEGIN
    SET NOCOUNT ON;

    -- Delete CommentLikes for all comments belonging to deleted videos
    DELETE FROM [dbo].[CommentLike]
    WHERE comment_id IN (
        SELECT c.comment_id 
        FROM [dbo].[Comment] c
        INNER JOIN deleted d ON c.video_id = d.video_id
    );

    -- Delete Comments
    DELETE FROM [dbo].[Comment]
    WHERE video_id IN (SELECT video_id FROM deleted);

    -- Delete Watch History
    DELETE FROM [dbo].[watch_history]
    WHERE video_id IN (SELECT video_id FROM deleted);

    -- Delete Video View Events
    DELETE FROM [dbo].[VideoViewEvent]
    WHERE video_id IN (SELECT video_id FROM deleted);

    -- Delete Playlist Videos
    DELETE FROM [dbo].[playlist_video]
    WHERE video_id IN (SELECT video_id FROM deleted);

    -- Delete Likes & Dislikes
    DELETE FROM [dbo].[Like]
    WHERE video_id IN (SELECT video_id FROM deleted);

    DELETE FROM [dbo].[dislike]
    WHERE video_id IN (SELECT video_id FROM deleted);

    -- Clean up polymorphic reports targeting the deleted videos
    DELETE FROM [dbo].[report]
    WHERE LOWER(reportable_type) = 'video' AND reportable_id IN (SELECT video_id FROM deleted);

    -- Clean up notifications related to the deleted videos
    DELETE FROM [dbo].[notification]
    WHERE related_entity_type = 'VIDEO' AND related_entity_id IN (SELECT video_id FROM deleted);

    -- Audit trail in SyncLog
    INSERT INTO [dbo].[SyncLog] ([file_name], [applied_at])
    SELECT
        'VIDEO_DELETED:' + CAST(video_id AS NVARCHAR(36)),
        SYSDATETIME()
    FROM deleted;

    -- Finally, physically delete the Video record
    DELETE FROM [dbo].[Video]
    WHERE video_id IN (SELECT video_id FROM deleted);
END;
GO


